SELECT n.name, mi1.info, MIN(t.production_year), MAX(t.production_year) FROM title as t, kind_type as kt, movie_info as mi1, info_type as it1, cast_info as ci, role_type as rt, name as n WHERE t.id = ci.movie_id AND t.id = mi1.movie_id AND mi1.info_type_id = it1.id AND t.kind_id = kt.id AND ci.person_id = n.id AND ci.movie_id = mi1.movie_id AND ci.role_id = rt.id AND (it1.id IN ('3','5','6')) AND (mi1.info IN ('Australia:M','Canada:14A','DTS','Dolby','Finland:K-16','Germany:18','History','Netherlands:AL','Portugal:M/16','Spain:T','Stereo','Switzerland:16','UK:12A','USA:TV-MA')) AND (UPPER(n.name) LIKE UPPER('%rya%')) AND (kt.kind IN ('episode','movie')) AND (rt.role IN ('actor','actress','cinematographer','composer','costume designer')) GROUP BY HASH(SUBSTRING(mi1.info FROM 1 FOR 8000) || '#' || SUBSTRING(n.name FROM 1 FOR 8000)), 2, 1 
